export function createCache(ttlMs, now) {
  const data = new Map();
  return {
    set(key, value) { data.set(key, { value, expires: now() + ttlMs }); },
    get(key) { const item = data.get(key); return item && item.expires < now() ? item.value : undefined; },
  };
}

export function createCache(ttlMs, now) {
  const data = new Map();
  return {
    set(key, value) { data.set(key, { value, expires: now() + ttlMs }); },
    get(key) { const item = data.get(key); return item && item.expires > now() ? item.value : undefined; },
  };
}
